public bool IsAnagramSort(string s, string t)
{
    if (s.Length != t.Length) return false;

    var sArr = s.ToCharArray();
    var tArr = t.ToCharArray();
    Array.Sort(sArr);
    Array.Sort(tArr);

    return sArr.SequenceEqual(tArr);
}

public bool IsAnagramHash(string s, string t)
{
    if (s.Length != t.Length) return false;

    var freq = new Dictionary<char, int>();

    foreach (char c in s)
    {
        freq[c] = freq.GetValueOrDefault(c, 0) + 1;
    }

    foreach (char c in t)
    {
        if (!freq.ContainsKey(c)) return false;
        freq[c]--;
        if (freq[c] == 0) freq.Remove(c);
    }

    return freq.Count == 0;
}

public bool IsAnagramArray(string s, string t)
{
    if (s.Length != t.Length) return false;

    int[] freq = new int[26];

    for (int i = 0; i < s.Length; i++)
    {
        freq[s[i] - 'a']++;
        freq[t[i] - 'a']--;
    }

    return freq.All(count => count == 0);
}
